// Operational-day helpers: a configurable teaching-week concept; Sunday is closed in this DEMO.
const schoolIsOpen=d=>{const wd=new Date(d+'T12:00:00Z').getUTCDay();return wd!==0 && !(S.holidays||[]).includes(d)};
function priorSchoolDay(d){let v=d;for(let i=0;i<370;i++){if(schoolIsOpen(v))return v;const a=new Date(v+'T12:00:00Z');a.setUTCDate(a.getUTCDate()-1);v=a.toISOString().slice(0,10)}return d}
function shiftDate(d,n){const v=new Date(d+'T12:00:00Z');v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)}
function schoolDaysBack(n,d=priorSchoolDay(TODAY())){const days=[];let cursor=d;for(let i=0;i<n;i++){cursor=priorSchoolDay(cursor);days.push(cursor);cursor=shiftDate(cursor,-1)}return days}
const operationalDate=()=>priorSchoolDay(TODAY());
const homeroomClass=id=>S.classes.find(c=>c.id===id)?.classTeacherId || S.staff.find(x=>x.roles.includes('teacher')&&x.classes.includes(id))?.id;
const myHomeroomClasses=()=>S.classes.filter(c=>homeroomClass(c.id)===S.activeUser);
const isHomeroomTeacher=s=>!!s&&currentStaff().roles.includes('teacher')&&homeroomClass(s.classId)===S.activeUser;
const classStudents=id=>S.students.filter(x=>x.classId===id);
function absentStreak(s,date=operationalDate()){
 let count=0;
 for(const day of schoolDaysBack(32,date)){
  const sheet=S.attendance[`${day}|${s.classId}`];
  if(!sheet?.submitted||sheet.statuses?.[s.id]!=='absent')break;
  count++;
 }
 return count;
}
function refreshDailyParentDraft(s,date){
 const r=S.dailyChecks[`${date}|${s.id}`]||{},sheet=S.attendance[`${date}|${s.classId}`];
 const attendanceStatus=sheet?.submitted?sheet.statuses?.[s.id]||'present':null;
 const issues=[['Books',r.books],['Uniform',r.uniform],['Homework',r.homework]].filter(x=>x[1]==='Needs attention').map(x=>x[0]+': needs attention');
 if(attendanceStatus==='late')issues.push('Punctuality: arrived late');
 const msgKey=`daily-care|${date}|${s.id}`;
 S.messages=S.messages.filter(x=>x.draftKey!==msgKey);
 if(issues.length&&s.consent){
  const labels={'Books':'പുസ്തകങ്ങൾ','Uniform':'യൂണിഫോം','Homework':'ഹോംവർക്ക്','Punctuality':'സമയനിഷ്ഠ'};
  const text=s.language==='ml'?`ഹെബ്രോൺ സ്കൂൾ · ${s.name} (${cls(s.classId)}), ${fmtDate(date)}: ${issues.map(x=>{const k=x.split(':')[0];return (labels[k]||k)+': ശ്രദ്ധ ആവശ്യമാണ്'}).join('; ')}. ${r.comment||''}`:`Hebron School · ${s.name}, ${cls(s.classId)} · ${fmtDate(date)}. Parent attention: ${issues.join('; ')}. ${r.comment||''} Thank you.`;
  S.messages.push({id:ID('msg'),studentId:s.id,type:'daily-student-care',text,status:'simulated',date,by:S.activeUser,draftKey:msgKey});
 }
 return issues.length;
}
function schoolSnapshot(date=operationalDate()){
 const classes=S.classes.map(c=>({c, sheet:S.attendance[`${date}|${c.id}`]}));
 const confirmed=classes.filter(x=>x.sheet?.submitted),pending=classes.filter(x=>!x.sheet?.submitted);
 const absent=confirmed.flatMap(({c,sheet})=>classStudents(c.id).filter(s=>sheet.statuses?.[s.id]==='absent'));
 const longLeave=S.students.map(s=>({student:s,days:absentStreak(s,date)})).filter(x=>x.days>2).sort((a,b)=>b.days-a.days);
 return {date,confirmed,pending,absent,longLeave};
}
function initOperationalDemo(){
 // Keep old browser demo records intact; add new fields without clearing existing fee data.
 if(!Array.isArray(S.escalations)){
  S.escalations=[
   {id:'esc-demo-1',studentId:'s2',teacherId:'teacher2',category:'Attendance',priority:'high',title:'Repeated absence — parent follow-up',detail:'Student has missed several consecutive class days. Please contact the guardian.',status:'open',createdAt:NOW(),updatedAt:NOW(),resolution:''},
   {id:'esc-demo-2',studentId:'s18',teacherId:'teacher3',category:'Homework',priority:'medium',title:'Homework repeatedly incomplete',detail:'Request guidance on arranging a supportive family check-in.',status:'open',createdAt:NOW(),updatedAt:NOW(),resolution:''},
   {id:'esc-demo-3',studentId:'s38',teacherId:'teacher1',category:'Wellbeing',priority:'medium',title:'Needs additional classroom support',detail:'Teacher would like a discussion with the principal.',status:'in_progress',createdAt:NOW(),updatedAt:NOW(),resolution:''}
  ];
 }
 if(!S.dailyChecks)S.dailyChecks={};
 if(!S.weeklyReports)S.weeklyReports={};
 if(!S.holidays)S.holidays=[];
 S.classes.forEach(c=>{if(!c.classTeacherId)c.classTeacherId=S.staff.find(x=>x.roles.includes('teacher')&&x.classes.includes(c.id))?.id||''});
 if(!S.operationalSampleSeeded && Object.keys(S.attendance||{}).length===0){
  // Sample only: last school day plus preceding class days. Leave 2 registers pending.
  schoolDaysBack(4).forEach((day,idx)=>{
   S.classes.forEach(c=>{
    if(idx===0&&['c4','c5'].includes(c.id))return;
    const statuses={};
    if(['lkg','c1'].includes(c.id)){
     const flagged=c.id==='lkg'?'s2':'s18';statuses[flagged]='absent';
    }
    if(idx===0){
     if(c.id==='c3')statuses['s37']='absent';
     if(c.id==='ukg')statuses['s10']='late';
     if(c.id==='c2')statuses['s27']='absent';
    }
    S.attendance[`${day}|${c.id}`]={statuses,submitted:true,submittedAt:NOW(),by:homeroomClass(c.id)||'principal'};
   });
  });
 }
 S.operationalSampleSeeded=true;
}
